-- Phiếu xuất độc lập: nháp có thể sửa, đã xác nhận thì khóa.
create table if not exists public."PHIEU_XUAT" (
  "ma_phieu_xuat" integer generated by default as identity primary key,
  "ma_phieu_code" varchar(80) not null unique,
  "ma_donhang" varchar not null references public."DON_HANG"("ma_donhang"),
  "ma_kho_xuat" integer not null references public."KHO"("ma_kho"),
  "trang_thai" varchar not null default 'NHAP' check ("trang_thai" in ('NHAP','DA_XAC_NHAN','DA_XUAT','HUY')),
  "nguoi_tao" varchar,
  "nguoi_xac_nhan" varchar,
  "ngay_tao" timestamptz not null default now(),
  "ngay_xac_nhan" timestamptz,
  "ghi_chu" text
);

create table if not exists public."CT_PHIEU_XUAT" (
  "ma_phieu_xuat" integer not null references public."PHIEU_XUAT"("ma_phieu_xuat") on delete cascade,
  "sku" varchar not null,
  "ma_kho_xuat" integer not null references public."KHO"("ma_kho"),
  "so_luong" integer not null check ("so_luong" > 0),
  "ten_sp_luc_xuat" varchar,
  "don_vi_luc_xuat" varchar,
  primary key ("ma_phieu_xuat", "sku", "ma_kho_xuat")
);

create or replace function public.confirm_dispatch_document(p_ma_phieu_xuat integer, p_nguoi_xac_nhan varchar, p_ma_kho_duoc_phep integer default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare doc record; line_row record; stock_quantity integer;
begin
  select * into doc from public."PHIEU_XUAT" where "ma_phieu_xuat" = p_ma_phieu_xuat for update;
  if not found then raise exception using errcode = 'P0070', message = 'DISPATCH_NOT_FOUND'; end if;
  if doc."trang_thai" <> 'NHAP' then raise exception using errcode = 'P0071', message = 'DISPATCH_NOT_EDITABLE'; end if;
  if not exists (select 1 from public."NHAN_VIEN" where "ma_nhan_vien" = p_nguoi_xac_nhan and "trang_thai" = 1) then raise exception using errcode = 'P0072', message = 'DISPATCHER_NOT_FOUND'; end if;
  if not exists (select 1 from public."CT_PHIEU_XUAT" where "ma_phieu_xuat" = p_ma_phieu_xuat) then raise exception using errcode = 'P0073', message = 'DISPATCH_HAS_NO_LINES'; end if;
  perform set_config('phub.stock_operation', 'XUAT_PHIEU_XUAT', true);
  perform set_config('phub.stock_reference', doc."ma_phieu_code", true);
  perform set_config('phub.stock_actor', p_nguoi_xac_nhan, true);
  for line_row in select * from public."CT_PHIEU_XUAT" where "ma_phieu_xuat" = p_ma_phieu_xuat order by "sku", "ma_kho_xuat" loop
    if p_ma_kho_duoc_phep is not null and line_row."ma_kho_xuat" <> p_ma_kho_duoc_phep then raise exception using errcode = 'P0074', message = 'WAREHOUSE_ACCESS_DENIED'; end if;
    select "so_luong_ton" into stock_quantity from public."TON_KHO" where "ma_kho" = line_row."ma_kho_xuat" and "sku" = line_row."sku" for update;
    if not found or stock_quantity < line_row."so_luong" then raise exception using errcode = 'P0075', message = 'INSUFFICIENT_STOCK'; end if;
    update public."TON_KHO" set "so_luong_ton" = stock_quantity - line_row."so_luong", "cap_nhat_luc" = now() where "ma_kho" = line_row."ma_kho_xuat" and "sku" = line_row."sku";
  end loop;
  update public."PHIEU_XUAT" set "trang_thai" = 'DA_XUAT', "nguoi_xac_nhan" = p_nguoi_xac_nhan, "ngay_xac_nhan" = now() where "ma_phieu_xuat" = p_ma_phieu_xuat;
  return jsonb_build_object('ma_phieu_xuat', p_ma_phieu_xuat, 'ma_phieu_code', doc."ma_phieu_code", 'trang_thai', 'DA_XUAT', 'nguoi_xac_nhan', p_nguoi_xac_nhan);
end; $$;

revoke all on function public.confirm_dispatch_document(integer, varchar, integer) from public, anon, authenticated;
grant execute on function public.confirm_dispatch_document(integer, varchar, integer) to service_role;

create or replace function public.create_dispatch_document(p_ma_donhang varchar, p_ma_kho_xuat integer, p_nguoi_tao varchar, p_ghi_chu text, p_lines jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare order_row record; doc_id integer; doc_code varchar;
begin
  select * into order_row from public."DON_HANG" where "ma_donhang" = p_ma_donhang for update;
  if not found then raise exception using errcode = 'P0080', message = 'ORDER_NOT_FOUND'; end if;
  if order_row."trang_thai" in ('DA_XUAT_KHO','HOAN_THANH','HUY') then raise exception using errcode = 'P0081', message = 'ORDER_NOT_EDITABLE'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception using errcode = 'P0082', message = 'DISPATCH_HAS_NO_LINES'; end if;
  doc_code := 'PX-' || p_ma_donhang || '-' || substr(md5(clock_timestamp()::text || random()::text), 1, 6);
  insert into public."PHIEU_XUAT"("ma_phieu_code","ma_donhang","ma_kho_xuat","nguoi_tao","ghi_chu") values (doc_code,p_ma_donhang,p_ma_kho_xuat,p_nguoi_tao,p_ghi_chu) returning "ma_phieu_xuat" into doc_id;
  insert into public."CT_PHIEU_XUAT"("ma_phieu_xuat","sku","ma_kho_xuat","so_luong") select doc_id, item->>'sku', (item->>'warehouse_id')::integer, (item->>'quantity')::integer from jsonb_array_elements(p_lines) item;
  return jsonb_build_object('ma_phieu_xuat',doc_id,'ma_phieu_code',doc_code,'trang_thai','NHAP');
end; $$;

create or replace function public.update_dispatch_document(p_ma_phieu_xuat integer, p_ma_donhang varchar, p_ma_kho_xuat integer, p_ghi_chu text, p_lines jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare doc record;
begin
  select * into doc from public."PHIEU_XUAT" where "ma_phieu_xuat" = p_ma_phieu_xuat for update;
  if not found then raise exception using errcode = 'P0083', message = 'DISPATCH_NOT_FOUND'; end if;
  if doc."trang_thai" <> 'NHAP' then raise exception using errcode = 'P0084', message = 'DISPATCH_NOT_EDITABLE'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception using errcode = 'P0082', message = 'DISPATCH_HAS_NO_LINES'; end if;
  update public."PHIEU_XUAT" set "ma_donhang"=p_ma_donhang,"ma_kho_xuat"=p_ma_kho_xuat,"ghi_chu"=p_ghi_chu where "ma_phieu_xuat"=p_ma_phieu_xuat;
  delete from public."CT_PHIEU_XUAT" where "ma_phieu_xuat"=p_ma_phieu_xuat;
  insert into public."CT_PHIEU_XUAT"("ma_phieu_xuat","sku","ma_kho_xuat","so_luong") select p_ma_phieu_xuat, item->>'sku', (item->>'warehouse_id')::integer, (item->>'quantity')::integer from jsonb_array_elements(p_lines) item;
  return jsonb_build_object('ma_phieu_xuat',p_ma_phieu_xuat,'trang_thai','NHAP');
end; $$;

revoke all on function public.create_dispatch_document(varchar,integer,varchar,text,jsonb) from public, anon, authenticated;
revoke all on function public.update_dispatch_document(integer,varchar,integer,text,jsonb) from public, anon, authenticated;
grant execute on function public.create_dispatch_document(varchar,integer,varchar,text,jsonb) to service_role;
grant execute on function public.update_dispatch_document(integer,varchar,integer,text,jsonb) to service_role;
